import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import path from 'path'
import { buildManifest } from './scripts/kits-manifest.mjs'

// Dev only: serve /kits/manifest.json generated from ./kits on every request, so adding kit files
// needs no extra step. In production the file is generated by `npm run kits:manifest` and served by nginx.
function kitsManifestDevPlugin() {
  return {
    name: 'kits-manifest-dev',
    apply: 'serve',
    configureServer(server) {
      server.middlewares.use('/kits/manifest.json', (req, res) => {
        res.setHeader('Content-Type', 'application/json')
        res.setHeader('Cache-Control', 'no-store')
        res.end(JSON.stringify(buildManifest(path.resolve('./kits'))))
      })
    },
  }
}

export default defineConfig({
  plugins: [react(), kitsManifestDevPlugin()],
})
